def longest_common_prefix(strings):
    if not strings:
        return ""
    shortest = min(strings, key=len)          # the prefix cannot be longer than the shortest string
    for i, char in enumerate(shortest):
        if any(s[i] != char for s in strings):
            return shortest[:i]               # position i is the first place where somebody disagrees
    return shortest
